-- 새 기술 38개 (D-73). 기존 기술은 건드리지 않는다 — 같은 slug 가 있으면 넣지 않음.
insert into public.techniques (position_id, slug, name_ko, name_en, aliases, steps, is_reviewed, source, sort_order)
select p.id, t.slug, t.name_ko, t.name_en, t.aliases, t.steps, t.is_reviewed, t.source, t.sort_order
from (values
  ('standing', 'takedown-to-grounded-back-control', '스탠딩 백 → 앉으며 백 테이크', 'Standing Back to Grounded Back Control', array['앉으며 훅 넣기','시트벨트 앉히기','Sit-Down Back Take']::text[], array['뒤에서 시트벨트(한 팔은 어깨 위, 한 팔은 겨드랑이 아래)로 상대 상체를 꽉 잡는다','한 발로 상대 무릎 뒤를 눌러 무릎을 꺾는다','상대를 뒤로 끌어당기며 옆으로 비스듬히 엉덩이를 바닥에 내린다','앉는 순간 다리 사이에 훅을 하나씩 넣는다','백 컨트롤로 끝난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 61),
  ('standing', 'shin-to-shin-pull', '신 투 신 가드 풀링', 'Shin-to-Shin Guard Pull', array['신투신 풀링','시팅 신 투 신','Pull to Shin-to-Shin']::text[], array['같은 쪽 소매(또는 깃과 소매)를 잡고 상대에게 가까이 다가선다','상대 앞다리 쪽으로 엉덩이를 낮춰 앉는다','앉으면서 내 정강이를 상대 앞다리 정강이 안쪽에 댄다','같은 쪽 손으로 그 다리 발목(바지)을 잡고, 반대 발은 바닥에 두어 버틴다','신 투 신 가드로 끝난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 62),
  ('closed-guard', 'triangle-from-clamp-guard', '트라이앵글 (클램프 가드)', 'Triangle from Clamp Guard', array['오버훅 트라이앵글','클램프 가드 트라이앵글','Overhook Triangle']::text[], array['오버훅으로 상대 한 팔을 내 겨드랑이에 꽉 끼우고, 같은 쪽 다리로 상대 등을 높이 눌러 자세를 무너뜨린다','다른 손으로 상대 반대 팔을 밀어 내 다리 사이 밖으로 뺀다','팔이 빠진 쪽 다리를 상대 목 뒤로 넘기고, 반대 다리 오금으로 그 발목을 걸어 잠근다','몸을 비스듬히 틀고 상대 머리를 당기며 무릎을 조여 트라이앵글 초크로 끝낸다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 39),
  ('closed-guard', 'armbar-from-clamp-guard', '암바 (클램프 가드)', 'Armbar from Clamp Guard', array['오버훅 암바','클램프 가드 암바','Overhook Armbar']::text[], array['오버훅으로 상대 팔을 겨드랑이에 끼우고, 그 손으로 상대 반대쪽 깃을 잡아 팔을 묶는다','반대쪽 발로 상대 골반을 밀어 몸을 비스듬히 돌린다(머리는 잡은 팔 반대쪽으로)','잡은 팔 반대쪽 다리를 상대 얼굴 앞으로 넘겨 머리를 누른다','무릎을 모으고 오버훅을 손목 쪽으로 미끄러뜨린 뒤 엉덩이를 들어 암바로 끝낸다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 40),
  ('open-guard', 'pass-k-guard', '케이 가드 패스', 'Pass K-Guard', array['K가드 패스','K-Guard Pass']::text[], array['상대가 K 가드를 만들면 허리를 낮추고 무릎을 모아 다리 사이 공간을 막는다','상대 안쪽 무릎을 손으로 바닥에 눌러 고정한다','걸린 다리를 뒤로 빼면서 엉덩이를 낮춘다','무릎을 상대 허벅지 위로 넘겨 니슬라이스로 지나간다','사이드 컨트롤로 끝난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 28),
  ('open-guard', 'k-guard-to-single-leg-x', '케이 가드 → 싱글 레그 X', 'K-Guard to Single Leg X', array['K가드 SLX','K가드에서 싱글엑스','K-Guard to SLX']::text[], array['K 가드에서 상대 앞다리 발목을 겨드랑이에 끼워 팔로 감싼다','상대 다리 사이에 넣은 안쪽 다리로 허벅지를 들어 올리며 엉덩이를 다리 밑으로 넣는다','그 안쪽 발을 상대 반대쪽 골반에 댄다','바깥쪽 다리로 상대 무릎 뒤를 감는다','싱글 레그 X 가드로 끝난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 29),
  ('butterfly-guard', 'butterfly-sweep-with-guillotine', '길로틴 스윕 (버터플라이)', 'Guillotine Sweep from Butterfly Guard', array['버터플라이 길로틴 스윕','길로틴 스윕','Butterfly Sweep with Guillotine']::text[], array['버터플라이 가드에서 상대 목을 감아 길로틴 그립을 잡는다','목을 감은 팔 쪽으로 몸을 기울이며 옆으로 눕는다','반대쪽 버터플라이 훅으로 상대 다리를 들어 올려 넘긴다','상대가 넘어가면 그립을 놓지 않고 따라 올라가 마운트에서 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 21),
  ('de-la-riva', 'rdlr-to-crab-ride', '리버스 데라히바 → 크랩 라이드', 'RDLR to Crab Ride', array['RDLR 크랩 라이드','크랩 라이드 진입','RDLR to Crab Ride']::text[], array['리버스 데라히바 훅을 상대 앞다리 안쪽에 걸고 반대 손으로 상대 뒤쪽 바지(또는 발목)를 잡는다','훅으로 앞다리를 바깥으로 밀어 상대 무게를 앞쪽으로 무너뜨린다','어깨로 굴러 상대 다리 사이 밑으로 들어가며 상대 엉덩이 뒤쪽으로 몸을 돌린다','상체를 일으켜 상대 허리 뒤에 붙고 두 발을 상대 무릎 안쪽에 걸어 크랩 라이드로 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 21),
  ('spider-lasso', 'double-sleeve-to-de-la-riva', '더블 슬리브 → 데라히바', 'Double Sleeve to De La Riva', array['더블 슬리브에서 데라히바','소매 가드 → 데라히바','Double Sleeve to DLR']::text[], array['상대 두 소매를 잡고 발로 상대 팔을 밀어 거리를 만든다','상대가 한 발을 앞으로 디디면 그 다리 쪽 소매를 놓고 그 손으로 발목(바지 끝)을 잡는다','같은 쪽 다리로 상대 다리를 바깥에서 감아 발등을 허벅지 안쪽에 건다','다른 손은 남은 소매를 계속 잡고, 반대 발은 골반이나 무릎에 둔다','데라히바 가드로 끝난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 36),
  ('half-guard', 'knee-shield-retention', '니 쉴드 유지 (눌릴 때)', 'Knee Shield Retention', array['니 쉴드 리텐션','Knee Shield Retention','무릎 방패 지키기']::text[], array['위 사람이 무릎을 눌러 오면 같은 쪽 손으로 그 무릎을 밀어 정강이 각도를 다시 세운다','반대 손은 상대 깃이나 어깨를 밀어 머리가 가까이 오지 못하게 막는다','엉덩이를 바깥으로 빼서(쉬림프) 정강이와 상대 몸 사이에 공간을 다시 만든다','정강이를 상대 골반이나 배에 다시 걸어 니 쉴드 하프가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 58),
  ('half-guard', 'guard-recovery-from-reverse-half-guard', '리버스 하프 → 하프가드 회복', 'Guard Recovery from Reverse Half Guard', array['리버스 하프 탈출','Escape Reverse Half Guard','힙 스위치 하프 회복']::text[], array['위 사람이 엉덩이를 돌려 내 다리 쪽을 보고 앉으면 다리 걸린 것을 풀지 말고 꽉 조인다','위쪽 손으로 상대 골반을 밀어 몸이 더 내려오지 못하게 막는다','엉덩이를 빼서 공간을 만들고 무릎을 상대 몸 앞으로 끌어 넣는다','상대가 다시 정면으로 돌아오면 니 쉴드나 언더훅을 잡아 하프가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 59),
  ('half-guard', 'pass-reverse-half', '리버스 하프 패스', 'Pass Reverse Half Guard', array['힙 스위치 패스','Reverse Half Pass','리버스 하프 → 사이드']::text[], array['하프가드 위에서 엉덩이를 돌려 상대 다리 쪽을 보고 앉고 팔로 상대 머리 쪽을 감싼다','걸리지 않은 발바닥으로 상대 무릎을 밀어 걸린 다리를 조금씩 뺀다','다리가 빠지면 엉덩이를 다시 상대 머리 쪽으로 돌려 가슴을 붙인다','크로스페이스와 언더훅을 잡아 사이드 컨트롤로 자리 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 60),
  ('half-guard', 'half-guard-to-quarter-guard', '하프가드 → 쿼터 가드 (탑)', 'Half Guard to Quarter Guard', array['쿼터 가드 만들기','Half to Quarter','다리 반쯤 빼기']::text[], array['하프가드 위에서 크로스페이스와 언더훅으로 상대를 바닥에 눕힌다','걸리지 않은 발이나 손으로 상대 위쪽 무릎을 바닥 쪽으로 누른다','걸린 다리의 무릎을 앞으로 빼서 발목만 걸린 상태로 만든다','가슴 압박을 유지한 채 쿼터 가드에서 마지막 발목을 뺄 준비를 한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 61),
  ('passing', 'cartwheel-pass', '카트휠 패스 (옆돌기 패스)', 'Cartwheel Pass', array['옆돌기 패스','카트윌 패스','Cartwheel Guard Pass']::text[], array['상대가 다리를 높이 들고 버티면 한 손으로 무릎을 눌러 다리를 한쪽으로 치운다','반대쪽 상대 몸통 옆 바닥에 두 손을 짚는다','다리를 차올려 옆돌기하듯 상대 다리 위를 넘어간다','착지하자마자 가슴을 상대 가슴에 붙여 누른다','사이드 컨트롤로 끝난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 68),
  ('side-control', 'buggy-choke', '버기 초크 (사이드 아래)', 'Buggy Choke from Bottom Side Control', array['버기 초크','Buggy Choke','사이드 아래 초크']::text[], array['사이드 아래에서 상대 머리 쪽 팔로 상대 목 뒤를 감는다','다른 손과 맞잡아 상대 목을 내 겨드랑이 쪽으로 끌어안는다','머리 쪽 다리를 들어 맞잡은 내 손목 위로 넘긴다','다른 다리로 그 발목을 걸어 다리를 삼각으로 잠근다','다리로 팔을 당기며 몸을 웅크려 조른다 → 탭']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 31),
  ('side-control', 'side-control-to-shoulder-of-justice', '숄더 오브 저스티스 (사이드)', 'Shoulder of Justice from Side Control', array['숄더 프레셔','Shoulder of Justice','어깨 압박']::text[], array['사이드 위에서 크로스페이스 팔을 상대 머리 뒤로 깊게 넣는다','내 어깨를 상대 턱 옆에 대고 고개를 반대쪽으로 민다','엉덩이는 낮추고 발끝으로 버텨 체중을 어깨에 싣는다','상대가 밀어내려고 팔을 뻗으면 그 팔을 노린다 → 기무라 · 아메리카나 · 마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 32),
  ('side-control', 'escape-shoulder-of-justice', '숄더 오브 저스티스 이스케이프', 'Escape Shoulder of Justice', array['어깨 압박 빠져나오기','숄더 프레셔 탈출','Shoulder of Justice Escape']::text[], array['턱을 당겨 목을 지키고 가까운 팔꿈치로 상대 골반을 막는다','먼 팔 팔뚝을 상대 목 아래에 끼워 프레임을 만든다','브릿지로 상대를 살짝 띄우고 고개를 상대 쪽으로 돌린다','엉덩이를 빼며 가까운 무릎을 넣어 다리를 감는다 → 하프가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 33),
  ('side-control', 'gift-wrap-maintenance', '기프트 랩 유지', 'Gift Wrap Maintenance', array['기프트 랩 컨트롤','Gift Wrap Control','선물 포장 그립 유지']::text[], array['상대 먼 팔을 목 앞으로 감아 머리 뒤로 넣은 내 손으로 손목을 잡는다','가슴으로 상대 어깨를 눌러 등을 바닥에 붙인다','상대가 팔을 빼려 하면 손목을 내 쪽으로 당겨 팔꿈치를 목에 붙인다','무게를 머리 쪽에 둔 채 다음 공격을 고른다 → 기무라 · 암바 · 백 테이크']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 34),
  ('north-south', 'reverse-mount-transition', '남북 → 리버스 마운트', 'North-South to Reverse Mount', array['리버스 마운트','Reverse Mount Transition','남북에서 리버스 마운트']::text[], array['남북 위에서 상대 가까운 팔을 겨드랑이 쪽에서 잡고 가슴으로 누른다','상대 몸 옆으로 돌며 체중을 상대 배 쪽으로 옮긴다','한 다리를 상대 배 위로 넘겨 다리 쪽을 보고 앉는다','무릎으로 상대 옆구리를 조여 고정한다 → 리버스 마운트 (암바 · 리스트락 연결)']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 8),
  ('kesa-gatame', 'ushiro-kesa-gatame-to-side-control', '리버스 곁누르기 → 사이드', 'Ushiro Kesa Gatame to Side Control', array['리버스 스카프 홀드 → 사이드','Reverse Kesa to Side Control','우시로 케사 → 사이드']::text[], array['리버스 곁누르기에서 상대 가까운 팔을 겨드랑이에 끼운 채 유지한다','엉덩이를 바닥에 끌며 몸을 돌려 상대 머리 쪽을 바라본다','무릎을 상대 엉덩이와 겨드랑이 옆에 붙인다','가슴을 상대 가슴에 붙이고 크로스페이스를 잡는다 → 사이드 컨트롤']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 18),
  ('kesa-gatame', 'ushiro-kesa-gatame-to-north-south', '리버스 곁누르기 → 남북', 'Ushiro Kesa Gatame to North-South', array['리버스 스카프 홀드 → 노스사우스','Reverse Kesa to North-South','우시로 케사 → 남북']::text[], array['리버스 곁누르기에서 가슴으로 상대 가슴을 계속 누른다','상대 머리 위쪽으로 다리를 한 걸음씩 걸어 돌아간다','상대 머리 위에서 무릎을 꿇고 가슴을 맞댄다','양팔로 상대 겨드랑이나 띠를 잡아 고정한다 → 남북']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 19),
  ('kesa-gatame', 'escape-ushiro-kesa-gatame', '리버스 곁누르기 이스케이프', 'Escape Ushiro Kesa Gatame', array['리버스 스카프 홀드 탈출','우시로 케사 이스케이프','Reverse Kesa Escape']::text[], array['갇힌 팔은 손을 내 배 쪽으로 당겨 팔꿈치를 몸에 붙인다','자유로운 손으로 상대 허리를 밀어 공간을 만든다','몸을 상대 쪽으로 돌리며 가까운 무릎을 상대 엉덩이 아래로 넣는다','다리로 상대 다리를 감는다 → 하프가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 20),
  ('mount', 'reverse-mount-to-mount', '리버스 마운트 → 마운트', 'Reverse Mount to Mount', array['리버스 마운트에서 마운트','역마운트 돌아앉기','Reverse Mount to Mount']::text[], array['리버스 마운트에서 양손을 상대 골반 옆 바닥에 짚는다','체중을 상대 배에 싣고 엉덩이를 살짝 든다','무릎을 빠르게 바꿔 디디며 몸을 상대 머리 쪽으로 돌린다','무릎을 상대 겨드랑이 쪽에 붙이고 엉덩이를 내린다','마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 40),
  ('mount', 'reverse-mount-to-side-control', '리버스 마운트 → 사이드', 'Reverse Mount to Side Control', array['리버스 마운트에서 사이드','Reverse Mount to Side Control']::text[], array['리버스 마운트에서 가슴을 상대 배 쪽으로 낮춘다','한 다리를 상대 몸 위로 넘겨 두 다리를 한쪽에 모은다','가슴을 붙인 채 몸을 상대 머리 쪽으로 돌린다','크로스페이스와 언더훅을 잡는다','사이드 컨트롤']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 41),
  ('mount', 'armbar-from-reverse-mount', '리버스 마운트 → 암바', 'Armbar from Reverse Mount', array['리버스 마운트 암바','Armbar from Reverse Mount']::text[], array['리버스 마운트에서 상대가 내 허리를 미는 팔을 양팔로 감아 가슴에 붙인다','잡은 팔 쪽으로 몸을 돌리며 엉덩이를 상대 어깨 쪽으로 옮긴다','반대 다리를 상대 얼굴 위로 넘긴다','무릎을 모은 채 뒤로 눕고 엉덩이를 들어 팔꿈치를 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 42),
  ('mount', 'escape-reverse-mount', '리버스 마운트 이스케이프 (하프가드로)', 'Escape Reverse Mount', array['리버스 마운트 탈출','Escape Reverse Mount']::text[], array['팔꿈치를 몸에 붙이고 양손으로 상대 허리 뒤를 받친다','브릿지로 상대를 내 다리 쪽으로 밀어낸다','엉덩이를 옆으로 빼며(새우빼기) 무릎을 상대 다리 사이로 넣는다','상대 한 다리를 내 두 다리로 감는다','하프가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 43),
  ('mount', 'bridge-from-reverse-mount', '리버스 마운트 브릿지 → 터틀', 'Bridge from Reverse Mount', array['리버스 마운트 브릿지','Bridge from Reverse Mount']::text[], array['발을 엉덩이 가까이 붙이고 팔꿈치를 몸에 붙인다','상대 무게가 다리 쪽으로 쏠린 순간 크게 브릿지한다','상대가 뜬 틈에 몸을 옆으로 틀어 무릎을 배 아래로 끌어온다','배를 바닥에 대고 팔꿈치와 무릎을 모은다','터틀']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 44),
  ('mount', 'explosive-bridge-to-turtle', '마운티드 크루시픽스 이스케이프 (브릿지 → 터틀)', 'Explosive Bridge to Turtle from Mounted Crucifix', array['마운티드 크루시픽스 탈출','크루시픽스 브릿지','Explosive Bridge to Turtle']::text[], array['갇힌 팔은 굽혀 몸 쪽으로 당겨 펴지지 않게 지킨다','발을 엉덩이 가까이 붙인다','상대 무게가 머리 쪽으로 쏠린 순간 크게 브릿지한다','상대가 뜬 틈에 몸을 옆으로 틀어 무릎을 끌어온다','터틀']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 45),
  ('back-control', 'body-triangle-escape-to-half-guard', '바디 트라이앵글 빠져나오기 (하프가드로)', 'Body Triangle Escape to Half Guard', array['바디 트라이앵글 탈출 → 하프','Body Triangle Escape to Half Guard']::text[], array['턱을 당기고 두 손으로 조르는 팔부터 막는다','상대 발목이 걸린 곳 위에 내 발을 얹어 눌러 잠금을 푼다','엉덩이를 바닥 쪽으로 밀어 등을 매트에 붙인다','상대 쪽으로 돌며 한 다리를 내 두 다리로 감는다','하프가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 26),
  ('back-control', 'back-control-to-crucifix', '백 → 크루시픽스', 'Back Control to Crucifix', array['백 크루시픽스','백에서 크루시픽스','Back Crucifix']::text[], array['백에서 상대가 두 손으로 조르는 팔을 막고 있을 때 시작한다','위쪽 다리를 들어 상대 위쪽 팔을 넘어 팔꿈치 안쪽에 건다','손으로 그 팔을 아래로 끌어내리고 두 다리 사이에 가둔다','상대 한 팔이 묶인 채 남은 손을 막는다','크루시픽스 — 초크 · 암바']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 27),
  ('turtle', 'crab-ride-to-back', '크랩 라이드 → 백 테이크', 'Crab Ride to Back Take', array['크랩 라이드 백','크랩 라이드 백 테이크','Crab Ride Back Take']::text[], array['상대 등 뒤에 앉아 두 발을 상대 허벅지 안쪽에 걸고 한 손으로 띠를 잡는다','상대가 일어나거나 앞으로 나가려 하면 띠를 당기며 훅으로 상대 엉덩이를 내 쪽으로 끌어온다','상대가 내 다리 위로 주저앉으면 가슴을 상대 등에 붙이고 시트벨트를 잡는다','두 훅을 상대 허벅지 안쪽에 다시 넣어 백 컨트롤로 끝낸다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 28),
  ('turtle', 'escape-from-crab-ride', '크랩 라이드 빠져나오기', 'Escape from Crab Ride', array['크랩 라이드 탈출','크랩 라이드 이스케이프','Crab Ride Escape']::text[], array['엉덩이를 바닥 쪽으로 낮춰 상대가 띠로 끌어당기지 못하게 한다','손으로 상대 발(훅) 하나를 내 무릎 바깥으로 밀어 뗀다','훅이 빠진 쪽으로 몸을 돌려 상대를 마주 본다','상대 다리 하나를 내 다리 사이에 가두며 하프가드로 정리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 29),
  ('turtle', 'turtle-to-rodeo-ride', '로데오 라이드 (터틀)', 'Rodeo Ride from Turtle', array['로데오 라이드','원 훅 라이드','Rodeo Ride','크로스 바디 라이드']::text[], array['터틀한 상대 뒤쪽 옆에서 가슴을 상대 등에 얹는다','가까운 쪽 발을 상대 허벅지 안쪽에 깊게 넣어 훅 하나를 건다','한 손은 상대 먼 쪽 깃(노기는 겨드랑이)을, 다른 손은 띠를 잡는다','엉덩이를 상대 엉덩이 위에 무겁게 올려 상대가 앉거나 돌지 못하게 누른다','상대가 버티면 훅 쪽으로 무게를 실어 눕히고 두 번째 훅을 넣어 백 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 30),
  ('submission-control', 'gogoplata-from-gogoplata-control', '고고플라타 마무리', 'Gogoplata Finish', array['고고플라타','Gogoplata','정강이 초크']::text[], array['내 정강이를 상대 목 앞에 가로로 대고, 발은 상대 어깨 너머로 넘긴 상태에서 시작한다','양손으로 상대 뒷머리를 깍지 끼어 잡는다(손이 닿으면 내 발끝을 잡아도 된다)','반대 다리로 상대 등이나 골반을 눌러 상대가 자세를 세우지 못하게 한다','머리를 당기면서 정강이를 목 쪽으로 밀어 넣어 탭을 받는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 29),
  ('submission-control', 'posture-up-from-gogoplata', '고고플라타 방어 (자세 세우기)', 'Gogoplata Defense (Posture Up)', array['고고플라타 탈출','Gogoplata Escape','Posture Up from Gogoplata']::text[], array['정강이가 목에 걸리면 바로 턱을 당기고 양손으로 정강이를 밀어 목에서 떼어 낸다','상대가 뒷머리를 당기는 손을 머리를 흔들어 털어 내거나 손으로 걷어 낸다','무릎을 상대 엉덩이에 붙이고 허리를 펴 상대 다리를 어깨 밖으로 떨어뜨린다','자세를 세운 채 상대 가드 안(오픈 가드 위)에서 다시 시작한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 30),
  ('submission-control', 'kimura-from-triangle-control', '기무라 (트라이앵글)', 'Kimura from Triangle Control', array['트라이앵글 → 기무라','Triangle to Kimura','삼각 기무라']::text[], array['트라이앵글을 걸었는데 상대가 버티면, 다리는 그대로 조인 채 갇힌 팔 손목을 잡는다','반대 팔을 상대 팔 위로 넘겨 내 손목을 잡아 기무라 그립(숫자 4)을 만든다','다리 삼각을 계속 조여 상대가 자세를 세우거나 팔을 빼지 못하게 한다','상대 손을 등 쪽으로 돌려 어깨를 비틀어 탭을 받는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 31),
  ('submission-control', 'kimura-trap-to-ushiro-kesa-gatame', '기무라 그립 → 리버스 곁누르기', 'Kimura Trap to Ushiro Kesa Gatame', array['기무라 트랩 → 우시로 케사','리버스 케사','Kimura to Reverse Kesa']::text[], array['위에서 기무라 그립(숫자 4)으로 상대 팔을 잡고 내 가슴에 붙인 상태에서 시작한다','팔을 놓지 않고 상대 머리 쪽으로 엉덩이를 돌려 상대 다리 쪽을 바라본다','상대 어깨 옆에 엉덩이를 내리고 다리를 넓게 벌려 무게를 싣는다','잡은 팔을 내 옆구리에 묶은 채 리버스 곁누르기(우시로 케사)로 누르고 다음 서브미션을 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 32),
  ('submission-control', 'americana-from-kimura-trap', '기무라 → 아메리카나 전환', 'Americana from Kimura Trap', array['기무라 아메리카나 전환','Kimura to Americana','아메리카나 (기무라 그립)']::text[], array['위에서 기무라 그립을 잡았는데 상대가 팔을 머리 쪽으로 밀어 올려 버틴다','팔이 머리 쪽으로 올라가면 그 손목을 바닥에 눌러 고정한다(팔꿈치는 직각)','반대 손을 상대 팔꿈치 아래로 넣어 내 손목을 잡아 아메리카나 그립으로 바꾼다','손목을 상대 엉덩이 쪽으로 미끄러뜨리며 팔꿈치를 들어 어깨를 비틀어 탭을 받는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 33)
) as t(position_slug, slug, name_ko, name_en, aliases, steps, is_reviewed, source, sort_order)
join public.positions p on p.slug = t.position_slug
on conflict (slug) do nothing;
